/* 导入模板资源：考试宝 Excel / Word 模板，内嵌 base64，离线与 file:// 均可下载 */
(function (global) {
  const Quiz = global.Quiz = global.Quiz || {};
  const DATA = {
    xlsx: {name: '考试宝Excel导入模板.xlsx', mime: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', b64: ''},
    docx: {name: '考试宝Word导入模板.docx', mime: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', b64: ''}
  };
  function decode(s) {
    if (typeof atob === 'function') {
      const bin = atob(s), out = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
      return out;
    }
    if (typeof Buffer !== 'undefined') return new Uint8Array(Buffer.from(s, 'base64'));
    throw new Error('当前环境不支持 base64 解码');
  }
  function meta(kind) { const d = DATA[kind]; if (!d) throw new Error('未知模板：' + kind); return d; }
  Quiz.templateAssets = {
    kinds: Object.keys(DATA),
    name: kind => meta(kind).name,
    mime: kind => meta(kind).mime,
    bytes: kind => decode(meta(kind).b64)
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = Quiz.templateAssets;
})(typeof window !== 'undefined' ? window : globalThis);
